	diffData, _ := os.ReadFile(assetsDir + "diff_kit_metabolism.json")
	var diff semio.KitDiff
	json.Unmarshal(diffData, &diff)

	applied := semio.ApplyKitDiff(orig, diff)

	fmt.Printf("applied.Files: %d, diffed.Files: %d\n", len(applied.Files), len(diffed.Files))
	fmt.Printf("applied.Folders: %d, diffed.Folders: %d\n", len(applied.Folders), len(diffed.Folders))
	fmt.Printf("applied.Types: %d, diffed.Types: %d\n", len(applied.Types), len(diffed.Types))
	fmt.Printf("applied.Designs: %d, diffed.Designs: %d\n", len(applied.Designs), len(diffed.Designs))
	fmt.Printf("applied.Tags: %d, diffed.Tags: %d\n", len(applied.Tags), len(diffed.Tags))
	fmt.Printf("applied.Concepts: %d, diffed.Concepts: %d\n", len(applied.Concepts), len(diffed.Concepts))
	fmt.Printf("applied.Ports: %d, diffed.Ports: %d\n", len(applied.Ports), len(diffed.Ports))
	fmt.Printf("applied.Authors: %d, diffed.Authors: %d\n", len(applied.Authors), len(diffed.Authors))

	diffedFileMap := make(map[string]semio.File)
	for _, f := range diffed.Files {
		diffedFileMap[f.Guid] = f
	}
	mismatches := 0
	for _, af := range applied.Files {
		df, ok := diffedFileMap[af.Guid]
		if !ok {
			fmt.Printf("File %s (%s) in applied but NOT in diffed\n", af.Guid, af.Name)
			mismatches++
			continue
		}
		if af.Name != df.Name {
			fmt.Printf("File %s name: %q vs %q\n", af.Guid, af.Name, df.Name)
			mismatches++
		}
		aBlobNil := af.Blob == nil
		dBlobNil := df.Blob == nil
		if aBlobNil != dBlobNil {
			fmt.Printf("File %s (%s) blob nil: applied=%v diffed=%v\n", af.Guid, af.Name, aBlobNil, dBlobNil)
			mismatches++
		} else if !aBlobNil && !dBlobNil && *af.Blob != *df.Blob {
			fmt.Printf("File %s (%s) blob content differs\n", af.Guid, af.Name)
			mismatches++
		}
		aMimeNil := af.Mime == nil
		dMimeNil := df.Mime == nil
		if aMimeNil != dMimeNil {
			fmt.Printf("File %s (%s) mime nil: applied=%v diffed=%v\n", af.Guid, af.Name, aMimeNil, dMimeNil)
			mismatches++
		} else if !aMimeNil && !dMimeNil && *af.Mime != *df.Mime {
			fmt.Printf("File %s (%s) mime: %q vs %q\n", af.Guid, af.Name, *af.Mime, *df.Mime)
			mismatches++
		}
		if af.CreatedAt != df.CreatedAt {
			fmt.Printf("File %s (%s) createdAt: %q vs %q\n", af.Guid, af.Name, af.CreatedAt, df.CreatedAt)
			mismatches++
		}
		if af.UpdatedAt != df.UpdatedAt {
			fmt.Printf("File %s (%s) updatedAt: %q vs %q\n", af.Guid, af.Name, af.UpdatedAt, df.UpdatedAt)
			mismatches++
		}
	}
	for _, df := range diffed.Files {
		found := false
		for _, af := range applied.Files {
			if af.Guid == df.Guid {
				found = true
				break
			}
		}
		if !found {
			fmt.Printf("File %s (%s) in diffed but NOT in applied\n", df.Guid, df.Name)
			mismatches++
		}
	}
	fmt.Printf("Total file mismatches: %d\n", mismatches)

	// Check deeper: Types
	diffedTypeMap := make(map[string]semio.Type)
	for _, t := range diffed.Types {
		diffedTypeMap[t.Guid] = t
	}
	typeMismatches := 0
	for _, at := range applied.Types {
		dt, ok := diffedTypeMap[at.Guid]
		if !ok {
			fmt.Printf("Type %s (%s) in applied but NOT in diffed\n", at.Guid, at.Name)
			typeMismatches++
			continue
		}
		if at.Name != dt.Name {
			fmt.Printf("Type %s name: %q vs %q\n", at.Guid, at.Name, dt.Name)
			typeMismatches++
		}
	}
	fmt.Printf("Total type mismatches: %d\n", typeMismatches)

	// Check designs  
	diffedDesignMap := make(map[string]semio.Design)
	for _, d := range diffed.Designs {
		diffedDesignMap[d.Guid] = d
	}
	designMismatches := 0
	for _, ad := range applied.Designs {
		dd, ok := diffedDesignMap[ad.Guid]
		if !ok {
			fmt.Printf("Design %s (%s) in applied but NOT in diffed\n", ad.Guid, ad.Name)
			designMismatches++
			continue
		}
		if ad.Name != dd.Name {
			fmt.Printf("Design %s name: %q vs %q\n", ad.Guid, ad.Name, dd.Name)
			designMismatches++
		}
		if len(ad.Pieces) != len(dd.Pieces) {
			fmt.Printf("Design %s pieces: %d vs %d\n", ad.Guid, len(ad.Pieces), len(dd.Pieces))
			designMismatches++
		}
		if len(ad.Connections) != len(dd.Connections) {
			fmt.Printf("Design %s connections: %d vs %d\n", ad.Guid, len(ad.Connections), len(dd.Connections))
			designMismatches++
		}
	}
	fmt.Printf("Total design mismatches: %d\n", designMismatches)
}

