cd /workspaces/semio && python3 -c "
import json
guid = '37ba7ec4-9023-4be7-9ab6-e0ebc80007f8'
with open('semio/assets/semio/kit_metabolism.json') as f:
    orig = json.load(f)
with open('semio/assets/semio/kit_metabolism_diffed.json') as f:
    diffed = json.load(f)

# Remove child designs
orig_designs = [d for d in orig['designs'] if not d.get('parent')]
diffed_designs = [d for d in diffed['designs'] if not d.get('parent')]

for d in orig_designs:
    if d['guid'] == guid:
        print(f'Original: {d[\"name\"]}, pieces: {len(d.get(\"pieces\", []))}')
        break
for d in diffed_designs:
    if d['guid'] == guid:
        print(f'Diffed: {d[\"name\"]}, pieces: {len(d.get(\"pieces\", []))}')
        break

# Find pieces difference
orig_piece_guids = set()
diffed_piece_guids = set()
for d in orig_designs:
    if d['guid'] == guid:
        orig_piece_guids = {p['guid'] for p in d.get('pieces', [])}
for d in diffed_designs:
    if d['guid'] == guid:
        diffed_piece_guids = {p['guid'] for p in d.get('pieces', [])}

added = diffed_piece_guids - orig_piece_guids
removed = orig_piece_guids - diffed_piece_guids
print(f'Added pieces: {len(added)}')
print(f'Removed pieces: {len(removed)}')
if added:
    for g in added:
        print(f'  Added: {g}')
"

