func (d *TypeDiff) SetField(field string) {
\tif d.setFields == nil {
\t\td.setFields = make(map[string]bool)
\t}
\td.setFields[field] = true
}

// MarshalJSON includes null for fields tracked in setFields.
func (d TypeDiff) MarshalJSON() ([]byte, error) {
\tresult := make(map[string]interface{})
\tif d.Name != nil {
\t\tresult["name"] = d.Name
\t} else if d.setFields != nil && d.setFields["name"] {
\t\tresult["name"] = nil
\t}
\tif d.Parent != nil {
\t\tresult["parent"] = d.Parent
