export const exportKit = async (kit: Kit, files: Map<string, Blob>): Promise<Blob> => {
  const JSZip = (await import("jszip")).default;

  // Serialize kit without blob data
  const kitForZip: Kit = {
    ...kit,
    files: kit.files?.map((f) => {
      const { blob, ...rest } = f;
      return rest;
    }),
  };

  const kitJson = serializeKit(kitForZip);

  const zip = new JSZip();
  zip.file("kit.json", kitJson);

  for (const [path, blob] of files.entries()) {
    const arrayBuffer = await blob.arrayBuffer();
    zip.file(path, new Uint8Array(arrayBuffer));
  }

  return await zip.generateAsync({ type: "blob" });
};

